/* Sarisa y elefante · fuentes.js
   Códice: protagonistas, fuentes antiguas (original, traducción y nota de juego) y glosario. */
"use strict";

/* ---------- códice: protagonistas, fuentes, glosario ---------- */
const CIMG=f=>`https://commons.wikimedia.org/wiki/Special:FilePath/${f}?width=320`;
const CPAGE=f=>`https://commons.wikimedia.org/wiki/File:${f}`;
const PEOPLE={
  ptolemy1:{n:'Ptolomeo I Sóter|Ptolemy I Soter',d:'c. 367–282',fac:'ptol',gr:'ΠΤΟΛΕΜΑΙΟΣ',img:'Ptolemy_I_Soter_Louvre_Ma849.jpg',cap:'Busto de Ptolomeo I, Museo del Louvre (Ma 849).|Bust of Ptolemy I, Louvre Museum (Ma 849).',
    b:'Compañero de Alejandro y sátrapa de Egipto desde 323; rey desde 305/304. Fundó la dinastía ptolemaica y acogió a Seleuco cuando este huyó de Babilonia en 316.|Companion of Alexander and satrap of Egypt from 323; king from 305/304. He founded the Ptolemaic dynasty and took in Seleucus when he fled Babylon in 316.'},
  seleucus1:{n:'Seleuco I Nicátor|Seleucus I Nicator',d:'c. 358–281',fac:'sel',gr:'ΣΕΛΕΥΚΟΣ',img:'Seleucus_I_Louvre.jpg',cap:'Busto identificado como Seleuco I, copia romana, Museo del Louvre.|Bust identified as Seleucus I, Roman copy, Louvre Museum.',
    b:'Oficial de Alejandro y sátrapa de Babilonia desde 320. Expulsado por Antígono en 316, regresó en 311 y construyó el mayor de los reinos helenísticos. Fue asesinado por Ptolomeo Cerauno en 281, poco después de vencer en Corupedio.|Officer of Alexander and satrap of Babylon from 320. Driven out by Antigonus in 316, he returned in 311 and built the largest of the Hellenistic kingdoms. He was murdered by Ptolemy Ceraunus in 281, shortly after his victory at Corupedium.'},
  demetrius1:{n:'Demetrio I Poliorcetes|Demetrius I Poliorcetes',d:'336–283',fac:'anti',gr:'ΔΗΜΗΤΡΙΟΣ',img:'Demetrios_Poliorketes_MAN_Napoli_Inv6149.jpg',cap:'Retrato identificado como Demetrio, copia romana, Museo Arqueológico Nacional de Nápoles (inv. 6149).|Portrait identified as Demetrius, Roman copy, National Archaeological Museum of Naples (inv. 6149).',
    b:'Hijo de Antígono. Vencido en Gaza en 312, debe su sobrenombre, «el sitiador de ciudades», a sus asedios. Fue rey de Macedonia entre 294 y 288 y murió cautivo de Seleuco.|Son of Antigonus. Defeated at Gaza in 312, he owes his epithet, “the besieger of cities”, to his sieges. He was king of Macedonia from 294 to 288 and died a captive of Seleucus.'},
  antigonus1:{n:'Antígono I Monoftalmo|Antigonus I Monophthalmus',d:'c. 382–301',fac:'anti',gr:'ΑΝΤΙΓΟΝΟΣ',
    b:'El «tuerto», el más poderoso de los sucesores de Alejandro tras 316. Tomó el título real en 306 junto a su hijo Demetrio. Murió en Ipso con más de ochenta años.|“The One-Eyed”, the most powerful of Alexander’s successors after 316. He took the royal title in 306 together with his son Demetrius. He died at Ipsus, over eighty years old.'},
  lysimachus:{n:'Lisímaco|Lysimachus',d:'c. 360–281',fac:'lys',gr:'ΛΥΣΙΜΑΧΟΣ',
    b:'Guardia personal de Alejandro, gobernó Tracia y, tras Ipso, buena parte de Asia Menor. En sus monedas aparece el retrato de Alejandro, no el suyo. Murió frente a Seleuco en Corupedio (281).|Bodyguard of Alexander, he ruled Thrace and, after Ipsus, much of Asia Minor. His coins carry Alexander’s portrait, not his own. He died fighting Seleucus at Corupedium (281).'},
  ptolemy4:{n:'Ptolomeo IV Filopátor|Ptolemy IV Philopator',d:'c. 244–204',fac:'ptol',gr:'ΠΤΟΛΕΜΑΙΟΣ',
    b:'Reinó desde 221. Venció en Rafia con una falange en la que combatían en masa egipcios armados a la macedonia. Polibio lo retrata como un rey indolente, dominado por sus cortesanos.|Reigned from 221. He won at Raphia with a phalanx in which Egyptians armed in the Macedonian manner fought in large numbers. Polybius portrays him as an indolent king ruled by his courtiers.'},
  antiochus3:{n:'Antíoco III Megas|Antiochus III the Great',d:'c. 242–187',fac:'sel',gr:'ΑΝΤΙΟΧΟΣ',img:'Antiochos_III.jpg',cap:'Retrato atribuido a Antíoco III, copia romana.|Portrait attributed to Antiochus III, Roman copy.',
    b:'Reinó desde 223. Recuperó las satrapías superiores en su anábasis (212–205), hasta Bactria y la India, y conquistó Celesiria en Panio (200). Su derrota en Magnesia llevó a la paz de Apamea (188). Murió en 187 saqueando un templo en Elimaida.|Reigned from 223. He recovered the upper satrapies in his anabasis (212–205), as far as Bactria and India, and conquered Coele-Syria at Panium (200). His defeat at Magnesia led to the Peace of Apamea (188). He died in 187 while plundering a temple in Elymais.'},
  scipio:{n:'Lucio Cornelio Escipión Asiático|Lucius Cornelius Scipio Asiaticus',d:'cónsul en 190|consul in 190',noYr:1,fac:'rom',gr:'L·CORNELIVS',
    b:'Hermano de Escipión el Africano, que lo acompañó como legado. Según Livio, el Africano estaba enfermo durante la batalla y el mando efectivo lo ejerció Gneo Domicio Ahenobarbo. Tras Magnesia recibió el sobrenombre de Asiático.|Brother of Scipio Africanus, who accompanied him as legate. According to Livy, Africanus was ill during the battle and effective command was held by Gnaeus Domitius Ahenobarbus. After Magnesia he took the cognomen Asiaticus.'},
  eumenes2:{n:'Eumenes II de Pérgamo|Eumenes II of Pergamon',d:'rey 197–159|king 197–159',noYr:1,fac:'rom',gr:'ΕΥΜΕΝΗΣ',
    b:'Aliado de Roma. En Magnesia mandó el ala derecha y sus tropas ligeras deshicieron la carga de los carros falcados. La paz de Apamea le entregó gran parte de Asia Menor.|Ally of Rome. At Magnesia he commanded the right wing, and his light troops broke up the charge of the scythed chariots. The Peace of Apamea gave him much of Asia Minor.'},
  nicanor:{n:'Nicanor|Nicanor',d:'activo en 312–311 a. C.|active 312–311 BC',noYr:1,fac:'anti',gr:'ΝΙΚΑΝΩΡ',
    b:'General de Antígono al mando de Media y de las satrapías superiores. Marchó contra Seleuco cuando este recuperó Babilonia, fue sorprendido de noche junto al Tigris y huyó por el desierto. Diodoro no dice qué fue de él.|General of Antigonus in command of Media and the upper satrapies. He marched against Seleucus when the latter recovered Babylon, was surprised by night near the Tigris and fled through the desert. Diodorus does not say what became of him.'},
  antiochus1:{n:'Antíoco I Sóter|Antiochus I Soter',d:'c. 324–261',fac:'sel',gr:'ΑΝΤΙΟΧΟΣ',
    b:'Hijo de Seleuco I y de la sogdiana Apama. Mandó la caballería de su padre en Ipso y fue corregente desde c. 292. Rey desde 281; según Apiano, debió el sobrenombre de «Salvador» a haber expulsado a los gálatas que habían invadido Asia.|Son of Seleucus I and the Sogdian Apama. He led his father’s cavalry at Ipsus and was co-ruler from c. 292. King from 281; according to Appian he owed the epithet “Saviour” to having driven out the Galatians who had invaded Asia.'},
  theodotas:{n:'Teodotas de Rodas|Theodotas of Rhodes',d:'siglo III a. C.|3rd century BC',noYr:1,fac:'sel',gr:'ΘΕΟΔΟΤΑΣ',
    b:'Solo lo conocemos por Luciano, que lo presenta como un hombre valiente y experto en táctica y le atribuye el plan de la batalla: ocultar los elefantes y lanzarlos contra la caballería y los carros de los gálatas.|We know him only from Lucian, who presents him as a brave man skilled in tactics and credits him with the plan of the battle: to hide the elephants and launch them against the Galatian cavalry and chariots.'},
  seleucus2:{n:'Seleuco II Calínico|Seleucus II Callinicus',d:'c. 265–225',fac:'sel',gr:'ΣΕΛΕΥΚΟΣ',
    b:'Rey desde 246. Su reinado empezó con la invasión de Ptolomeo III (tercera guerra siria) y siguió con la guerra contra su hermano Hierax; entretanto se perdieron Bactria y Partia. Murió al caer del caballo.|King from 246. His reign began with the invasion of Ptolemy III (Third Syrian War) and went on with the war against his brother Hierax; meanwhile Bactria and Parthia were lost. He died from a fall from his horse.'},
  hierax:{n:'Antíoco Hierax|Antiochus Hierax',d:'c. 263–226',fac:'reb',gr:'ΑΝΤΙΟΧΟΣ',
    b:'Hermano menor de Seleuco II; «Hierax» significa «halcón». Gobernó Asia Menor como rey rival hasta que Átalo I de Pérgamo lo expulsó. Murió en Tracia a manos de unos bandidos.|Younger brother of Seleucus II; “Hierax” means “hawk”. He ruled Asia Minor as a rival king until Attalus I of Pergamon drove him out. He died in Thrace at the hands of bandits.'},
  molon:{n:'Molón|Molon',d:'m. 220 a. C.|d. 220 BC',noYr:1,fac:'reb',gr:'ΜΟΛΩΝ',
    b:'Sátrapa de Media con Antíoco III. Se sublevó en 222 junto a su hermano Alejandro, sátrapa de Pérside, tomó Seleucia del Tigris y acuñó moneda como rey. Vencido en Apolonia, se quitó la vida.|Satrap of Media under Antiochus III. He rebelled in 222 together with his brother Alexander, satrap of Persis, took Seleucia on the Tigris and struck coins as king. Defeated at Apollonia, he took his own life.'},
  euthydemus:{n:'Eutidemo I de Bactria|Euthydemus I of Bactria',d:'rey c. 230–200 a. C.|king c. 230–200 BC',noYr:1,fac:'bac',gr:'ΕΥΘΥΔΗΜΟΣ',
    b:'Griego de Magnesia que se hizo con el trono de Bactria tras eliminar a los descendientes de Diódoto. Resistió a Antíoco III en Bactra hasta lograr un acuerdo: conservó el título de rey y entregó sus elefantes.|A Greek from Magnesia who took the throne of Bactria after removing the descendants of Diodotus. He held out against Antiochus III at Bactra until he obtained an agreement: he kept the title of king and handed over his elephants.'},
  scopas:{n:'Escopas de Etolia|Scopas of Aetolia',d:'m. 196 a. C.|d. 196 BC',noYr:1,fac:'ptol',gr:'ΣΚΟΠΑΣ',
    b:'Estratego de la Liga Etolia que pasó al servicio de los Ptolomeos como jefe de mercenarios. Reconquistó Judea en el invierno de 201–200 y fue derrotado en Panio. Acusado de conspirar, fue ejecutado en Alejandría.|A general of the Aetolian League who entered Ptolemaic service as a commander of mercenaries. He reconquered Judaea in the winter of 201–200 and was defeated at Panium. Accused of conspiracy, he was executed at Alexandria.'},
  glabrio:{n:'Manio Acilio Glabrión|Manius Acilius Glabrio',d:'cónsul en 191 a. C.|consul in 191 BC',noYr:1,fac:'rom',gr:'M·ACILIVS',
    b:'Hombre nuevo, cercano a los Escipiones. Como cónsul expulsó a Antíoco III de Grecia en las Termópilas y sometió después a los etolios. Celebró el triunfo en 190.|A new man, close to the Scipios. As consul he drove Antiochus III out of Greece at Thermopylae and then subdued the Aetolians. He celebrated a triumph in 190.'},
  cato:{n:'Marco Porcio Catón|Marcus Porcius Cato',d:'234–149',fac:'rom',gr:'M·PORCIVS',
    b:'Cónsul en 195 y más tarde censor. En las Termópilas sirvió a las órdenes de Glabrión y dirigió la marcha nocturna por el Calídromo, de la que, según Plutarco, él mismo dejó un relato muy elogioso.|Consul in 195 and later censor. At Thermopylae he served under Glabrio and led the night march over Callidromon, of which, according to Plutarch, he himself left a very flattering account.'},
  antiochus4:{n:'Antíoco IV Epífanes|Antiochus IV Epiphanes',d:'c. 215–164',fac:'sel',gr:'ΑΝΤΙΟΧΟΣ',
    b:'Hijo de Antíoco III y rehén en Roma tras la paz de Apamea. Rey desde 175. Invadió Egipto dos veces (170–168) hasta que Roma lo obligó a retirarse. Su política en Jerusalén provocó la revuelta de los Macabeos. Murió en Persia.|Son of Antiochus III and a hostage at Rome after the Peace of Apamea. King from 175. He invaded Egypt twice (170–168) until Rome forced him to withdraw. His policy in Jerusalem provoked the Maccabean revolt. He died in Persia.'},
  ptolemy6:{n:'Ptolomeo VI Filométor|Ptolemy VI Philometor',d:'c. 186–145',fac:'ptol',gr:'ΠΤΟΛΕΜΑΙΟΣ',
    b:'Rey desde 180, de niño bajo la regencia de su madre Cleopatra I y después de Euleo y Leneo. Vencido por Antíoco IV en su juventud, acabó como árbitro de Siria y murió de las heridas recibidas junto al Enóparas.|King from 180, as a child under the regency of his mother Cleopatra I and then of Eulaeus and Lenaeus. Beaten by Antiochus IV in his youth, he ended as arbiter of Syria and died of the wounds he received by the Oenoparas.'},
  judas:{n:'Judas Macabeo|Judas Maccabeus',d:'m. 160 a. C.|d. 160 BC',noYr:1,fac:'jud',gr:'ΙΟΥΔΑΣ',
    b:'Tercer hijo del sacerdote Matatías. Desde 166 dirigió la revuelta contra los seléucidas, venció a varios de sus generales y en 164 purificó el Templo de Jerusalén, lo que recuerda la fiesta de Janucá. Cayó en Elasa.|Third son of the priest Mattathias. From 166 he led the revolt against the Seleucids, defeated several of their generals and in 164 purified the Temple in Jerusalem, which the feast of Hanukkah commemorates. He fell at Elasa.'},
  lysias:{n:'Lisias|Lysias',d:'m. 162 a. C.|d. 162 BC',noYr:1,fac:'sel',gr:'ΛΥΣΙΑΣ',
    b:'Antíoco IV le confió el gobierno del oeste del reino y la tutela de su hijo. Regente de Antíoco V desde 164, venció en Bet Zacarías. Él y el niño rey fueron ejecutados cuando Demetrio I tomó el poder.|Antiochus IV entrusted him with the government of the west of the kingdom and the guardianship of his son. Regent for Antiochus V from 164, he won at Beth Zechariah. He and the boy king were put to death when Demetrius I seized power.'},
  eleazar:{n:'Eleazar Avarán|Eleazar Avaran',d:'m. 162 a. C.|d. 162 BC',noYr:1,fac:'jud',gr:'ΕΛΕΑΖΑΡ',
    b:'Cuarto de los cinco hijos de Matatías. Murió en Bet Zacarías aplastado por el elefante que acababa de matar, convencido de que llevaba al rey.|Fourth of the five sons of Mattathias. He died at Beth Zechariah, crushed by the elephant he had just killed in the belief that it carried the king.'},
  bacchides:{n:'Báquides|Bacchides',d:'activo en 162–157 a. C.|active 162–157 BC',noYr:1,fac:'sel',gr:'ΒΑΚΧΙΔΗΣ',
    b:'«Amigo» del rey Demetrio I y gobernador de la región del otro lado del Éufrates. Dirigió varias campañas en Judea para sostener al sumo sacerdote Alcimo, venció a Judas en Elasa y acabó pactando con Jonatán.|A “Friend” of King Demetrius I and governor of the region beyond the Euphrates. He led several campaigns in Judaea in support of the high priest Alcimus, defeated Judas at Elasa and ended by coming to terms with Jonathan.'},
  balas:{n:'Alejandro Balas|Alexander Balas',d:'rey 150–145 a. C.|king 150–145 BC',noYr:1,fac:'reb',gr:'ΑΛΕΞΑΝΔΡΟΣ',
    b:'Se presentó como hijo de Antíoco IV con el apoyo de Pérgamo, Egipto y Roma, y venció a Demetrio I en 150. Se casó con Cleopatra Tea, hija de Ptolomeo VI, a quien su padre entregó después a Demetrio II.|He presented himself as a son of Antiochus IV with the backing of Pergamon, Egypt and Rome, and defeated Demetrius I in 150. He married Cleopatra Thea, daughter of Ptolemy VI, whom her father later gave to Demetrius II.'},
  demetrius2:{n:'Demetrio II Nicátor|Demetrius II Nicator',d:'c. 160–125',fac:'sel',gr:'ΔΗΜΗΤΡΙΟΣ',
    b:'Hijo de Demetrio I. Desembarcó en Cilicia en 147 con mercenarios cretenses y, aliado con Ptolomeo VI, recuperó el trono. Reinó de 145 a 138, cayó prisionero de los partos y volvió a reinar de 129 a 125.|Son of Demetrius I. He landed in Cilicia in 147 with Cretan mercenaries and, allied with Ptolemy VI, recovered the throne. He reigned from 145 to 138, fell prisoner to the Parthians and reigned again from 129 to 125.'},
  antiochus7:{n:'Antíoco VII Sidetes|Antiochus VII Sidetes',d:'c. 159–129',fac:'sel',gr:'ΑΝΤΙΟΧΟΣ',
    b:'Hermano de Demetrio II, criado en Side de Panfilia. Rey desde 138, eliminó al usurpador Trifón, sometió Jerusalén y en 130 recuperó Mesopotamia y Media. Fue el último rey seléucida poderoso.|Brother of Demetrius II, brought up at Side in Pamphylia. King from 138, he eliminated the usurper Tryphon, subdued Jerusalem and in 130 recovered Mesopotamia and Media. He was the last powerful Seleucid king.'},
  phraates2:{n:'Fraates II de Partia|Phraates II of Parthia',d:'rey c. 132–127 a. C.|king c. 132–127 BC',noYr:1,fac:'par',gr:'ΑΡΣΑΚΗΣ',
    b:'Hijo de Mitrídates I. Para dividir a los seléucidas liberó a Demetrio II, su cautivo. Tras vencer a Antíoco VII pensó en invadir Siria, pero murió combatiendo a los nómadas sacas en el este. En sus monedas, como todos los reyes partos, lleva el nombre dinástico de Arsaces.|Son of Mithridates I. To divide the Seleucids he released Demetrius II, his captive. After defeating Antiochus VII he thought of invading Syria, but died fighting the Saka nomads in the east. On his coins, like every Parthian king, he bears the dynastic name Arsaces.'},
  antiochus12:{n:'Antíoco XII Dioniso|Antiochus XII Dionysus',d:'rey desde c. 87 a. C.|king from c. 87 BC',noYr:1,fac:'sel',gr:'ΑΝΤΙΟΧΟΣ',
    b:'El menor de los hijos de Antíoco VIII. Reinó en Damasco mientras sus hermanos y primos se disputaban el resto de Siria. Hizo dos campañas contra los nabateos; en la segunda murió.|The youngest of the sons of Antiochus VIII. He reigned at Damascus while his brothers and cousins fought over the rest of Syria. He made two campaigns against the Nabataeans; in the second he died.'},
  aretas3:{n:'Aretas III|Aretas III',d:'rey c. 87–62 a. C.|king c. 87–62 BC',noYr:1,fac:'nab',gr:'ΑΡΕΤΑΣ',
    b:'Rey de los nabateos, con capital en Petra. Tras la muerte de Antíoco XII ocupó Damasco, donde acuñó moneda con leyenda griega y el título de «Filheleno».|King of the Nabataeans, with his capital at Petra. After the death of Antiochus XII he occupied Damascus, where he struck coins with a Greek legend and the title “Philhellene”.'}
};
const PER=urn=>`https://scaife.perseus.org/reader/${urn}/`;
const SOURCES={
  diod83:{ref:'Diodoro 19.83.2|Diodorus 19.83.2',work:'Biblioteca histórica|Library of History',lang:'grc',url:PER('urn:cts:greekLit:tlg0060.tlg001.perseus-grc6:19.83'),
    o:'προέταξαν δὲ τῆς στάσεως ταύτης τοὺς κομίζοντας χάρακα σεσιδηρωμένον καὶ δεδεμένον ἀλύσεσιν, ὃν παρεσκευάσαντο πρὸς τὴν τῶν ἐλεφάντων ἔφοδον· ταθέντος γὰρ τούτου ῥᾴδιον ἦν εἴργειν τὰ θηρία τῆς εἰς τοὔμπροσθεν πορείας.',
    tr:'Delante de esta posición colocaron a los que llevaban una empalizada guarnecida de hierro y unida con cadenas, que habían preparado contra la acometida de los elefantes; pues, una vez tendida, era fácil impedir a las fieras avanzar hacia delante.|In front of this position they placed the men carrying a palisade fitted with iron and bound with chains, which they had prepared against the onset of the elephants; for once it was stretched out, it was easy to keep the beasts from advancing.',
    g:'La unidad «Portadores de la empalizada» gana +2 ATQ contra elefantes, y los elefantes que la atacan sufren −2.|The “Palisade bearers” unit gains +2 ATK against elephants, and elephants attacking it suffer −2.'},
  diod84:{ref:'Diodoro 19.84.3|Diodorus 19.84.3',work:'Biblioteca histórica|Library of History',lang:'grc',url:PER('urn:cts:greekLit:tlg0060.tlg001.perseus-grc6:19.84'),
    o:'τὸ γὰρ γένος τοῦτο κατὰ μὲν τοὺς ὁμαλοὺς καὶ μαλακοὺς τόπους ἀνυπόστατον παρέχεται κατὰ στόμα τὴν ῥώμην, ἐν δὲ τοῖς τραχέσι καὶ δυσβάτοις τελέως ἄπρακτον ἔχει τὴν ἀλκὴν διὰ τὴν τῶν ποδῶν μαλακότητα.',
    tr:'Pues esta especie, en los terrenos llanos y blandos, opone de frente una fuerza irresistible, pero en los ásperos y difíciles de transitar tiene un vigor del todo inútil por la blandura de sus patas.|For this kind of animal, on level and soft ground, presents an irresistible strength head-on, but on rough and difficult ground its might is wholly ineffective because of the softness of its feet.',
    g:'Los elefantes pierden 1 de ataque en terreno abrupto y les cuesta 3 puntos de movimiento entrar en él.|Elephants lose 1 attack on rough ground and need 3 movement points to enter it.'},
  plut29a:{ref:'Plutarco, Demetrio 29.3|Plutarch, Demetrius 29.3',work:'Vidas paralelas|Parallel Lives',lang:'grc',url:PER('urn:cts:greekLit:tlg0007.tlg057.perseus-grc2:29'),
    o:'Δημήτριος ἔχων τοὺς πλείστους καὶ κρατίστους τῶν ἱππέων Ἀντιόχῳ τῷ Σελεύκου συνέπεσε, καὶ μέχρι τροπῆς τῶν πολεμίων λαμπρῶς ἀγωνισάμενος ἐν τῇ διώξει σοβαρᾷ καὶ φιλοτίμῳ παρὰ καιρὸν γενομένῃ τὴν νίκην διέφθειρεν. αὐτὸς μὲν γὰρ οὐκ ἔσχε πάλιν ἀναστρέψας συμμῖξαι τοῖς πεζοῖς τῶν ἐλεφάντων ἐν μέσῳ γενομένων.',
    tr:'Demetrio, con la mayor parte y lo mejor de la caballería, chocó con Antíoco, el hijo de Seleuco, y, tras combatir brillantemente hasta poner en fuga a los enemigos, echó a perder la victoria con una persecución arrogante y ambiciosa, emprendida a destiempo. Pues él mismo no pudo dar media vuelta y unirse de nuevo a la infantería, al haberse interpuesto los elefantes.|Demetrius, with the greater and best part of the cavalry, fell upon Antiochus the son of Seleucus and, after fighting brilliantly until the enemy were routed, ruined the victory by a haughty and ambitious pursuit made out of season. For he himself could not turn back and rejoin the infantry, since the elephants had come in between.',
    g:'Las fichas no se pueden atravesar y entrar junto a un enemigo detiene el movimiento: tres unidades de elefantes bastan para cortar el camino a la caballería de Demetrio.|Counters cannot be passed through and moving next to an enemy stops movement: three elephant units are enough to cut off Demetrius’ cavalry.'},
  plut29b:{ref:'Plutarco, Demetrio 29.5|Plutarch, Demetrius 29.5',work:'Vidas paralelas|Parallel Lives',lang:'grc',url:PER('urn:cts:greekLit:tlg0007.tlg057.perseus-grc2:29'),
    o:'καὶ τοῦτο μέχρι παντὸς ἐλπίζων καὶ περισκοπῶν τὸν υἱὸν ἅμα πολλῶν ἀκοντισμάτων εἰς αὐτὸν ἀφεθέντων ἔπεσε· καὶ τῶν ἄλλων ἀπολιπόντων ὀπαδῶν καὶ φίλων μόνος παρέμεινε τῷ νεκρῷ Θώραξ ὁ Λαρισσαῖος.',
    tr:'Y, esperando esto hasta el final y buscando con la mirada a su hijo, cayó cuando le arrojaron a la vez muchos dardos; y, abandonado por los demás acompañantes y amigos, solo Tórax de Larisa permaneció junto al cadáver.|And, hoping for this to the very end and looking about for his son, he fell when many javelins were hurled at him at once; and when the rest of his attendants and friends had abandoned him, only Thorax of Larissa remained beside the body.',
    g:'«Esto» es la llegada de Demetrio en su ayuda, que Antígono acaba de anunciar. En el juego, si cae el general, su ejército se rinde.|“This” is Demetrius coming to his aid, which Antigonus has just announced. In the game, if the general falls, his army surrenders.'},
  pol845:{ref:'Polibio 5.84.5–6|Polybius 5.84.5–6',work:'Historias|Histories',lang:'grc',url:PER('urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:5.84'),
    o:'τὰ δὲ πλεῖστα τῶν τοῦ Πτολεμαίου θηρίων ἀπεδειλία τὴν μάχην, ὅπερ ἔθος ἐστὶ ποιεῖν τοῖς Λιβυκοῖς ἐλέφασι· τὴν γὰρ ὀσμὴν καὶ φωνὴν οὐ μένουσιν, ἀλλὰ καὶ καταπεπληγμένοι τὸ μέγεθος καὶ τὴν δύναμιν, ὥς γʼ ἐμοὶ δοκεῖ, φεύγουσιν εὐθέως ἐξ ἀποστήματος τοὺς Ἰνδικοὺς ἐλέφαντας· ὃ καὶ τότε συνέβη γενέσθαι.',
    tr:'Pero la mayoría de las fieras de Ptolomeo rehuyó el combate, como suelen hacer los elefantes libios: no soportan el olor ni el bramido, sino que, sobrecogidos además por el tamaño y la fuerza, según me parece, huyen enseguida, desde lejos, de los elefantes indios; y eso es lo que ocurrió también entonces.|But most of Ptolemy’s beasts shrank from the fight, as Libyan elephants are wont to do: they cannot abide the smell and the trumpeting, but, struck also by their size and strength, as it seems to me, they flee at once from a distance before the Indian elephants; and this is what happened then too.',
    g:'Los elefantes africanos tienen menos ataque y defensa, y sufren −1 cuando atacan a elefantes indios.|African elephants have lower attack and defence, and suffer −1 when attacking Indian elephants.'},
  pol843:{ref:'Polibio 5.84.3–4|Polybius 5.84.3–4',work:'Historias|Histories',lang:'grc',url:PER('urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:5.84'),
    o:'ἔστι γὰρ ἡ τῶν ζῴων μάχη τοιαύτη τις. συμπλέξαντα καὶ παρεμβαλόντα τοὺς ὀδόντας εἰς ἀλλήλους ὠθεῖ τῇ βίᾳ, διερειδόμενα περὶ τῆς χώρας, ἕως ἂν κατακρατῆσαν τῇ δυνάμει θάτερον παρώσῃ τὴν θατέρου προνομήν· ὅταν δʼ ἅπαξ ἐγκλῖναν πλάγιον λάβῃ, τιτρώσκει τοῖς ὀδοῦσι, καθάπερ οἱ ταῦροι τοῖς κέρασι.',
    tr:'Pues la lucha de estos animales es más o menos así: trabados y con los colmillos encajados unos en otros, empujan con todas sus fuerzas, disputándose el terreno, hasta que uno, imponiéndose por su fuerza, aparta la trompa del otro; y una vez que lo ha hecho ceder y lo coge de costado, lo hiere con los colmillos, como los toros con los cuernos.|For the fighting of these animals is something like this: locked together and with their tusks thrust against each other, they push with all their force, contending for the ground, until one, prevailing by strength, forces aside the other’s trunk; and once it has made it give way and caught it on the flank, it gores it with its tusks, as bulls do with their horns.',
    g:'Atacar a un enemigo al que ya tocan otras unidades propias da hasta +2 por flanqueo.|Attacking an enemy already touched by other friendly units gives up to +2 for flanking.'},
  liv40:{ref:'Livio 37.40.1–2|Livy 37.40.1–2',work:'Ab urbe condita',lang:'la',url:PER('urn:cts:latinLit:phi0914.phi001.perseus-lat2:37.40'),
    o:'decem et sex milia peditum more Macedonum armati fuere, qui phalangitae appellabantur. haec media acies fuit, in fronte in decem partes divisa; partes eas interpositis binis elephantis distinguebat; a fronte introrsus in duos et triginta ordines armatorum acies patebat.',
    tr:'Dieciséis mil infantes iban armados a la manera macedonia; se los llamaba falangitas. Estos formaban el centro, dividido en el frente en diez secciones; las separaba interponiendo dos elefantes entre cada una; desde el frente hacia atrás, la formación tenía una profundidad de treinta y dos filas.|Sixteen thousand foot were armed in the Macedonian fashion; they were called phalangites. They formed the centre, divided along the front into ten sections; he separated these sections by placing two elephants between each; from front to rear the line was thirty-two ranks deep.',
    g:'En el despliegue de Magnesia, las falanges seléucidas alternan con unidades de elefantes.|In the Magnesia deployment, the Seleucid phalanxes alternate with elephant units.'},
  liv41:{ref:'Livio 37.41.9–10|Livy 37.41.9–10',work:'Ab urbe condita',lang:'la',url:PER('urn:cts:latinLit:phi0914.phi001.perseus-lat2:37.41'),
    o:'[Eumenes] Cretenses sagittarios funditoresque et iaculatores cum aliquot turmis equitum non confertos, sed quam maxime possent dispersos excurrere iubet et ex omnibus simul partibus tela ingerere. haec velut procella partim vulneribus missilium undique coniectorum partim clamoribus dissonis ita consternavit equos, ut repente velut effrenati passim incerto cursu ferrentur.',
    tr:'[Eumenes] ordena a los arqueros cretenses, a los honderos y a los lanzadores de jabalina, con algunos escuadrones de caballería, salir no en formación cerrada, sino lo más dispersos posible, y arrojar proyectiles desde todas partes a la vez. Esto, como una tempestad, en parte por las heridas de los proyectiles lanzados desde todos lados, en parte por los gritos discordantes, espantó de tal modo a los caballos que de pronto, como desbocados, corrían en todas direcciones sin rumbo fijo.|[Eumenes] orders the Cretan archers, the slingers and the javelin-men, with some troops of horse, to run out not in close order but as dispersed as they could, and to shower missiles from all sides at once. This, like a storm, partly through the wounds of missiles hurled from every side, partly through the discordant shouting, so terrified the horses that suddenly, as if unbridled, they rushed about everywhere in no fixed course.',
    g:'Los proyectiles ganan +2 contra carros y elefantes, y los carros dañados pueden entrar en pánico y arrollar a su propio bando.|Missiles gain +2 against chariots and elephants, and damaged chariots may panic and trample their own side.'},
  /* Fuentes de las batallas añadidas. El texto original se ha cotejado con Scaife Viewer (Perseus y First1KGreek) y, para Justino, con The Latin Library.
     Los dos fragmentos de Diodoro que no están en línea en esas bibliotecas llevan un resumen (sum) en lugar de la cita literal. */
  diod92:{ref:'Diodoro 19.92.3–4|Diodorus 19.92.3–4',work:'Biblioteca histórica|Library of History',lang:'grc',url:PER('urn:cts:greekLit:tlg0060.tlg001.perseus-grc6:19.92'),
    o:'ἐπιγενομένης δὲ νυκτὸς καὶ τῶν περὶ Νικάνορα καταπεφρονηκότως καὶ ῥᾳθύμως ἐχόντων τὰ περὶ τὰς φυλακὰς ἐπιπεσὼν ὁ Σέλευκος ἄφνω πολλὴν ταραχὴν καὶ κατάπληξιν κατεσκεύασε· συναψάντων γὰρ μάχην τῶν Περσῶν συνέβη τόν τε σατράπην αὐτῶν Εὔαγρον πεσεῖν καί τινας τῶν ἄλλων ἡγεμόνων. οὗ συμβάντος οἱ πλείους τῶν στρατιωτῶν τὰ μὲν τὸν κίνδυνον καταπεπληγμένοι, τὰ δὲ προσκόπτοντες τοῖς ὑπʼ Ἀντιγόνου πραττομένοις μετεβάλοντο πρὸς Σέλευκον.',
    tr:'Cuando se hizo de noche, y mientras los de Nicanor montaban la guardia con desdén y descuido, Seleuco cayó de repente sobre ellos y causó gran confusión y espanto; pues, al trabar combate los persas, ocurrió que cayeron su sátrapa Evagro y algunos de los demás jefes. Después de esto, la mayoría de los soldados, en parte aterrados por el peligro, en parte descontentos con la conducta de Antígono, se pasaron a Seleuco.|When night came on, and while Nicanor’s men were keeping their watch contemptuously and carelessly, Seleucus fell upon them suddenly and caused great confusion and panic; for when the Persians joined battle, it happened that their satrap Evagrus fell along with some of the other leaders. After this, most of the soldiers, partly terrified at the danger, partly offended by the conduct of Antigonus, went over to Seleucus.',
    g:'Las unidades de Nicanor empiezan con la fuerza reducida (7 u 8 de 10) y la batalla se juega de noche. Los pantanos, donde Seleuco ocultó a sus hombres, frenan a todos, y más a la caballería y a la falange.|Nicanor’s units begin at reduced strength (7 or 8 out of 10) and the battle is fought at night. The marshes, where Seleucus hid his men, slow everyone, cavalry and phalanx most of all.'},
  just17:{ref:'Justino 17.1.9–12|Justin 17.1.9–12',work:'Epítome de las Historias filípicas de Pompeyo Trogo|Epitome of the Philippic Histories of Pompeius Trogus',lang:'la',url:'https://www.thelatinlibrary.com/justin/17.html',
    o:'Ultimum hoc certamen conmilitonum Alexandri fuit et velut ad exemplum fortunae par reservatum. Lysimachus quattuor et LXX annos natus erat, Seleucus septem et LXX. Sed in hac aetate utrique animi iuveniles erant imperiique cupiditatem insatiabilem gerebant; quippe cum orbem terrarum duo soli tenerent, angustis sibi metis inclusi videbantur vitaeque finem non annorum spatio, sed imperii terminis metiebantur.',
    tr:'Este fue el último combate entre los compañeros de armas de Alejandro, una pareja reservada, por así decir, para ejemplo de la fortuna. Lisímaco tenía setenta y cuatro años; Seleuco, setenta y siete. Pero a esa edad los dos tenían ánimos juveniles y un deseo insaciable de poder; pues, aunque ellos dos solos poseían el orbe, se sentían encerrados en límites estrechos y medían el final de la vida no por el número de los años, sino por las fronteras del imperio.|This was the last contest between Alexander’s fellow soldiers, a pair reserved, as it were, for an example of fortune. Lysimachus was seventy-four years old, Seleucus seventy-seven. But at that age both had youthful spirits and an insatiable desire for power; for although the two of them alone held the world, they felt themselves shut in within narrow bounds, and measured the end of life not by the span of years but by the limits of empire.',
    g:'Los dos reyes mandan en persona su caballería de guardia. Si cae uno de ellos, su ejército se rinde, como ocurrió con el de Lisímaco.|Both kings lead their guard cavalry in person. If one of them falls, his army surrenders, as that of Lysimachus did.'},
  luc9:{ref:'Luciano, Zeuxis 9|Lucian, Zeuxis 9',work:'Zeuxis o Antíoco|Zeuxis or Antiochus',lang:'grc',url:PER('urn:cts:greekLit:tlg0062.tlg057.perseus-grc2:9'),
    o:'τούτους ἐκέλευσεν ὁ Θεοδότας τέως μὲν ἔχειν ὡς οἷόν τε κατακρύψαντας, ὡς μὴ κατάδηλοι εἶεν ὑπερφαινόμενοι τοῦ στρατοῦ, ἐπειδὰν δὲ σημήνῃ ὁ σαλπιγκτὴς καὶ δέῃ συμπλέκεσθαι καὶ εἰς χεῖρας ἰέναι καὶ ἡ ἵππος ἡ τῶν πολεμίων ἐπελαύνηται καὶ τὰ ἅρματα οἱ Γαλάται ἀνοίξαντες τὴν φάλαγγα καὶ διαστήσαντες ἐπαφῶσι, τότε ἀνὰ τέτταρας μὲν τῶν ἐλεφάντων ἀπαντᾶν ἐφʼ ἑκάτερα τοῖς ἱππεῦσι, τοὺς ὀκτὼ δὲ ἀντεπαφεῖναι τοῖς ἁρματηλάταις καὶ συνωριασταῖς· εἰ γὰρ τοῦτο γένοιτο, φοβηθήσονται αὐτῶν, ἔφη, οἱ ἵπποι καὶ ἐς τοὺς Γαλάτας αὖθις ἐμπεσοῦνται φεύγοντες.',
    tr:'Teodotas mandó tenerlos entretanto lo más escondidos posible, para que no se les viera sobresalir por encima del ejército; y, cuando el trompeta diera la señal y hubiera que trabar combate y llegar a las manos, y la caballería enemiga cargara y los gálatas, abriendo y separando la falange, soltaran los carros, entonces cuatro elefantes por cada lado debían salir al encuentro de los jinetes, y los otros ocho lanzarse contra los conductores de los carros de guerra y de los de dos caballos. «Si así se hace —dijo—, sus caballos se espantarán y, al huir, caerán de nuevo sobre los gálatas».|Theodotas ordered them to be kept hidden as far as possible for the time being, so that they should not be seen towering above the army; and when the trumpeter gave the signal and it was time to engage and come to close quarters, and the enemy cavalry charged and the Galatians, opening the phalanx and parting it, let loose the chariots, then four of the elephants on either side were to meet the horsemen, and the other eight to be launched against the drivers of the war chariots and of the two-horse chariots. “If this is done,” he said, “their horses will take fright and, as they flee, will fall back upon the Galatians.”',
    g:'Los elefantes de Antíoco tienen la regla «terror»: +2 ATQ contra caballería y carros. Además, la caballería que ataca a un elefante, o junto a él, sufre −2.|Antiochus’ elephants have the “terror” rule: +2 ATK against cavalry and chariots. In addition, cavalry attacking an elephant, or next to one, suffers −2.'},
  luc11:{ref:'Luciano, Zeuxis 11|Lucian, Zeuxis 11',work:'Zeuxis o Antíoco|Zeuxis or Antiochus',lang:'grc',url:PER('urn:cts:greekLit:tlg0062.tlg057.perseus-grc2:11'),
    o:'ὁ δὲ καὶ δακρύσας, ὥς φασιν, Αἰσχυνώμεθα, ἔφη, ὦ στρατιῶται, οἷς γε ἡ σωτηρία ἐν ἑκκαίδεκα τούτοις θηρίοις ἐγένετο· ὡς εἰ μὴ τὸ καινὸν τοῦ θεάματος ἐξέπληξε τοὺς πολεμίους, τί ἂν ἡμεῖς ἦμεν πρὸς αὐτούς; ἔπειτα τῷ τροπαίῳ κελεύει ἄλλο μηδέν, ἐλέφαντα δὲ μόνον ἐγκολάψαι.',
    tr:'Pero él, incluso entre lágrimas, según cuentan, dijo: «Avergoncémonos, soldados, nosotros, cuya salvación ha estado en estas dieciséis bestias; pues, si la novedad del espectáculo no hubiera aterrado a los enemigos, ¿qué habríamos sido nosotros frente a ellos?». Después ordena que en el trofeo no se grabe ninguna otra cosa, sino solo un elefante.|But he, even in tears, as they say, declared: “Let us be ashamed, soldiers, we whose safety lay in these sixteen beasts; for if the novelty of the sight had not terrified the enemy, what would we have been against them?” Then he orders nothing else to be carved on the trophy, but only an elephant.',
    g:'Según Luciano (Zeuxis 10), los carros dieron media vuelta y segaron con sus hoces a los propios gálatas: en el juego, los carros dañados entran con facilidad en pánico y arrollan a las unidades propias que tienen al lado.|According to Lucian (Zeuxis 10), the chariots wheeled about and mowed down the Galatians themselves with their scythes: in the game, damaged chariots panic easily and trample the friendly units next to them.'},
  just27:{ref:'Justino 27.2.11–12|Justin 27.2.11–12',work:'Epítome de las Historias filípicas de Pompeyo Trogo|Epitome of the Philippic Histories of Pompeius Trogus',lang:'la',url:'https://www.thelatinlibrary.com/justin/27.html',
    o:'In eo proelio virtute Gallorum victor quidem Antiochus fuit, sed Galli arbitrantes Seleucum in proelio cecidisse in ipsum Antiochum arma vertere, liberius depopulaturi Asiam, si omnem stirpem regiam extinxissent. Quod ubi sensit Antiochus, velut a praedonibus auro se redemit societatemque cum mercennariis suis iungit.',
    tr:'En aquella batalla Antíoco resultó, sí, vencedor gracias al valor de los gálatas; pero los gálatas, creyendo que Seleuco había caído en el combate, volvieron las armas contra el propio Antíoco, pues saquearían Asia con más libertad si extinguían toda la estirpe real. Cuando Antíoco se dio cuenta, se rescató con oro, como de unos bandidos, y selló una alianza con sus propios mercenarios.|In that battle Antiochus was indeed the victor, thanks to the valour of the Galatians; but the Galatians, thinking that Seleucus had fallen in the fighting, turned their arms on Antiochus himself, since they would plunder Asia more freely if they wiped out the whole royal line. When Antiochus perceived this, he ransomed himself with gold, as if from brigands, and concluded an alliance with his own mercenaries.',
    g:'Hierax alinea cuatro bandas de mercenarios gálatas: golpean fuerte mientras están enteras (furor), pero son frágiles ante los proyectiles.|Hierax fields four bands of Galatian mercenaries: they hit hard while intact (fury) but are fragile against missiles.'},
  pol553:{ref:'Polibio 5.53.2–4|Polybius 5.53.2–4',work:'Historias|Histories',lang:'grc',url:PER('urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:5.53'),
    o:'ἐπὶ μὲν οὖν τοῦ δεξιοῦ κέρως ἔταξε πρώτους τοὺς ξυστοφόρους ἱππεῖς, ἐπιστήσας Ἄρδυν, κεκριμένον ἄνδρα περὶ τὰς πολεμικὰς πράξεις· τούτοις δὲ παρέθηκε τοὺς συμμαχικοὺς Κρῆτας, ὧν εἴχοντο Γαλάται Ῥιγόσαγες· παρὰ δὲ τούτους ἔθηκε τοὺς ἀπὸ τῆς Ἑλλάδος ξένους καὶ μισθοφόρους, οἷς ἑπόμενον παρενέβαλε τὸ τῆς φάλαγγος σύστημα. τὸ δʼ εὐώνυμον κέρας ἀπέδωκε τοῖς Ἑταίροις προσαγορευομένοις, οὖσιν ἱππεῦσι. τὰ δὲ θηρία πρὸ τῆς δυνάμεως ἐν διαστήμασι κατέστησε, δέκα τὸν ἀριθμὸν ὄντα.',
    tr:'En el ala derecha colocó primero a los jinetes lanceros, al mando de Ardis, hombre probado en las acciones de guerra; junto a ellos puso a los aliados cretenses, a los que seguían los gálatas rigosages; a continuación situó a los extranjeros y mercenarios de Grecia, y tras ellos intercaló el cuerpo de la falange. El ala izquierda la asignó a los llamados Compañeros, que eran jinetes. Las fieras, que eran diez, las dispuso delante del ejército, a intervalos.|On the right wing he posted first the lancer cavalry, putting in command Ardys, a man proven in the operations of war; next to them he placed the Cretan allies, and next to these came the Rhigosages Galatians; beside these he set the foreigners and mercenaries from Greece, and following them he inserted the body of the phalanx. The left wing he assigned to those called Companions, who were cavalry. The beasts, ten in number, he stationed in front of the army at intervals.',
    g:'El despliegue de Antíoco sigue a Polibio de derecha a izquierda: lanceros, cretenses, gálatas, mercenarios, falange y hetairoi, con los elefantes delante. El rey manda la derecha.|Antiochus’ deployment follows Polybius from right to left: lancers, Cretans, Galatians, mercenaries, phalanx and Hetairoi, with the elephants in front. The king commands the right.'},
  pol554:{ref:'Polibio 5.54.1–3|Polybius 5.54.1–3',work:'Historias|Histories',lang:'grc',url:PER('urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:5.54'),
    o:'μετὰ δὲ ταῦτα ποιησαμένων τῶν δυνάμεων τὴν ἐπαγωγήν, τὸ μὲν δεξιὸν κέρας τοῦ Μόλωνος διετήρησε τὴν πίστιν καὶ συνέβαλε τοῖς περὶ τὸν Ζεῦξιν ἐρρωμένως, τὸ δʼ εὐώνυμον ἅμα τῷ συνιὸν εἰς ὄψιν ἐλθεῖν τῷ βασιλεῖ μετεβάλετο πρὸς τοὺς πολεμίους· οὗ γενομένου συνέβη τοὺς μὲν περὶ τὸν Μόλωνα διατραπῆναι, τοὺς δὲ τοῦ βασιλέως ἐπιρρωσθῆναι διπλασίως. ὁ δὲ Μόλων συννοήσας τὸ γεγονὸς καὶ πανταχόθεν ἤδη κυκλούμενος, λαβὼν πρὸ ὀφθαλμῶν τὰς ἐσομένας περὶ αὑτὸν αἰκίας, ἐὰν ὑποχείριος γένηται καὶ ζωγρίᾳ ληφθῇ, προσήνεγκε τὰς χεῖρας ἑαυτῷ.',
    tr:'Después, cuando los ejércitos avanzaron al ataque, el ala derecha de Molón mantuvo la lealtad y chocó con vigor contra los de Zeuxis; pero la izquierda, en cuanto al avanzar quedó a la vista del rey, se pasó al enemigo. Con ello, los de Molón se desmoralizaron y los del rey cobraron doble ánimo. Molón, al comprender lo ocurrido y verse ya rodeado por todas partes, se puso ante los ojos los tormentos que le esperaban si caía en manos del rey y lo cogían vivo, y se quitó la vida.|After this, when the armies advanced to the attack, Molon’s right wing kept faith and engaged Zeuxis’ men vigorously, but the left, as soon as in advancing it came in sight of the king, went over to the enemy. When this happened, Molon’s men lost heart and the king’s were doubly encouraged. Molon, realising what had happened and already surrounded on all sides, set before his eyes the torments that awaited him if he fell into the king’s hands and was taken alive, and laid hands on himself.',
    g:'La caballería y los tiradores del ala izquierda de Molón son «vacilantes»: −2 ATQ y −2 DEF cuando el rey está a 2 casillas o menos.|The cavalry and skirmishers of Molon’s left wing are “wavering”: −2 ATK and −2 DEF when the king is within 2 squares.'},
  pol1049a:{ref:'Polibio 10.49.4–5|Polybius 10.49.4–5',work:'Historias|Histories',lang:'grc',url:PER('urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:10.49'),
    o:'τοὺς γὰρ ἱππεῖς ἐπυνθάνετο τῶν ὑπεναντίων τὰς μὲν ἡμέρας ἐφεδρεύειν παρὰ τὸ χεῖλος τοῦ ποταμοῦ, τὰς δὲ νύκτας ὑποχωρεῖν πρός τινα πόλιν οὐκ ἔλαττον εἴκοσι σταδίων διέχουσαν. διανύσας δὲ νύκτωρ τὴν καταλειπομένην ὁδόν, ἅτε τῶν πεδίων ἱππασίμων ὑπαρχόντων, ἔφθασε περαιώσας τὸν ποταμὸν ἅμα τῷ φωτὶ τὸ πλεῖστον μέρος τῆς μεθʼ ἑαυτοῦ δυνάμεως.',
    tr:'Pues se había enterado de que la caballería enemiga montaba guardia de día junto a la orilla del río, pero de noche se retiraba a una ciudad que distaba no menos de veinte estadios. Tras recorrer de noche el camino que le quedaba, pues la llanura era buena para los caballos, se adelantó y, al rayar el día, ya había pasado al otro lado del río la mayor parte de las fuerzas que llevaba consigo.|For he had learned that the enemy cavalry kept guard by day at the edge of the river, but at night withdrew to a city no less than twenty stades away. Having covered the remaining distance by night, the plains being good for riding, he succeeded in getting the greater part of the force he had with him across the river by daybreak.',
    g:'El río solo se cruza por los vados, que cuestan 3 puntos de movimiento. Quien ataca desde un vado, o se defiende en él, sufre −1.|The river can be crossed only at the fords, which cost 3 movement points. Whoever attacks from a ford, or defends in one, suffers −1.'},
  pol1049b:{ref:'Polibio 10.49.10 y 14|Polybius 10.49.10, 14',work:'Historias|Histories',lang:'grc',url:PER('urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:10.49'),
    o:'πολλοὶ μὲν οὖν ἀμφοτέρων διεφθάρησαν, ἐπεκράτησαν δὲ τῆς πρώτης ἱππαρχίας οἱ μετὰ τοῦ βασιλέως· τῆς δὲ δευτέρας καὶ τρίτης ἐπιφερομένης ἐπιέζοντο καὶ κακῶς ἀπήλλαττον. […] ἐν δὲ τούτῳ τῷ κινδύνῳ τὸν μὲν ἵππον συμβαίνει ἀποθανεῖν τραυματισθέντα, αὐτὸν δὲ πληγέντα διὰ τοῦ στόματος ἀποβαλεῖν τινας τῶν ὀδόντων, καθόλου δὲ φήμην ἐπʼ ἀνδρείᾳ περιποιήσασθαι τότε μάλιστα.',
    tr:'Muchos de ambos bandos perecieron, pero los que estaban con el rey se impusieron a la primera hiparquía; al cargar la segunda y la tercera, se vieron apurados y lo pasaban mal. […] En aquel combate su caballo murió herido, y él mismo, golpeado en la boca, perdió algunos dientes; y, en general, fue entonces cuando ganó mayor fama de valor.|Many on both sides were killed, but the king’s men got the better of the first hipparchy; when the second and third charged, they were hard pressed and fared badly. […] In this fight his horse was wounded and died, and he himself, struck in the mouth, lost some of his teeth; and, all in all, it was then above all that he won a reputation for courage.',
    g:'Antíoco y su caballería real son tropa escogida (+1 ATQ, +1 DEF), pero empiezan casi solos al otro lado del río. Si el rey cae, se pierde la batalla.|Antiochus and his royal cavalry are picked troops (+1 ATK, +1 DEF), but they begin almost alone on the far bank. If the king falls, the battle is lost.'},
  pol1618:{ref:'Polibio 16.18.7|Polybius 16.18.7',work:'Historias|Histories',lang:'grc',url:PER('urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:16.18'),
    o:'μετὰ δὲ ταῦτά φησι τὰ θηρία προτάξαι τῆς φάλαγγος ἐν διαστήματι καὶ τοὺς μετʼ Ἀντιπάτρου Ταραντίνους, τὰ δὲ μεταξὺ τῶν θηρίων πληρῶσαι τοῖς τοξόταις καὶ σφενδονήταις, αὐτὸν δὲ μετὰ τῆς ἑταιρικῆς ἵππου καὶ τῶν ὑπασπιστῶν κατόπιν ἐπιστῆναι τοῖς θηρίοις.',
    tr:'Después dice [Zenón] que colocó delante de la falange, a intervalos, a las fieras y a los tarentinos de Antípatro, que llenó los espacios entre las fieras con los arqueros y honderos, y que él mismo se situó detrás de las fieras con la caballería de los Compañeros y los hipaspistas.|After this, he [Zeno] says, he posted the beasts in front of the phalanx at intervals, together with Antipater’s Tarentines, filled the spaces between the beasts with the archers and slingers, and himself took up position behind the beasts with the Companion cavalry and the hypaspists.',
    g:'El despliegue sigue el relato de Zenón: elefantes, tarentinos y tiradores delante de la falange, y el rey detrás con hetairoi e hipaspistas. El ala derecha de Escopas toca las estribaciones del monte.|The deployment follows Zeno’s account: elephants, Tarentines and skirmishers in front of the phalanx, and the king behind with Hetairoi and hypaspists. Scopas’ right wing rests on the foothills.'},
  pol1619:{ref:'Polibio 16.18.8–10|Polybius 16.18.8–10',work:'Historias|Histories',lang:'grc',url:PER('urn:cts:greekLit:tlg0543.tlg001.perseus-grc2:16.18'),
    o:'ταῦτα δʼ ὑποθέμενος, τὸν μὲν νεώτερον Ἀντίοχόν φησιν, ὃν ἐν τοῖς ἐπιπέδοις ἔθηκε κατὰ τὸ λαιὸν τῶν πολεμίων ἔχοντα τὴν κατάφρακτον ἵππον, τοῦτον ἐκ τῆς ὀρεινῆς ἐπενεχθέντα τρέψασθαι τοὺς ἱππέας τοὺς περὶ τὸν Πτολεμαῖον τὸν Ἀερόπου καὶ καταδιώκειν, ὃς ἐτύγχανε τοῖς Αἰτωλοῖς ἐπιτεταγμένος ἐν τοῖς ἐπιπέδοις ἐπὶ τῶν εὐωνύμων, τὰς δὲ φάλαγγας, ἐπεὶ συνέβαλλον ἀλλήλαις, μάχην ποιεῖν ἰσχυράν. ὅτι δὲ συμβαλεῖν ἀδύνατον ἦν τῶν θηρίων καὶ τῶν ἱππέων καὶ τῶν εὐζώνων προτεταγμένων, τοῦτʼ οὐκέτι συνορᾷ.',
    tr:'Sentado esto, dice que Antíoco el Joven, al que había colocado en el llano frente a la izquierda del enemigo con la caballería acorazada, cargó desde la montaña, puso en fuga a los jinetes de Ptolomeo, hijo de Aéropo —que era quien mandaba a los etolios en el llano, a la izquierda—, y los persiguió; y que las falanges, al chocar entre sí, libraron un combate encarnizado. Pero que era imposible que chocaran, estando delante las fieras, los jinetes y la infantería ligera, eso ya no lo advierte.|Having laid this down, he says that the younger Antiochus, whom he had placed on the level ground opposite the enemy’s left with the armoured cavalry, charged down from the hills, routed the horsemen of Ptolemy son of Aeropus — who was in command of the Aetolians on the plain, on the left — and pursued them; and that the phalanxes, when they met, fought a stubborn battle. But that it was impossible for them to meet, with the beasts, the cavalry and the light troops posted in front, this he fails to see.',
    g:'Polibio señala la contradicción de Zenón: los catafractos están en el llano y, a la vez, cargan desde la montaña. En el escenario forman en el llano, frente a la caballería etolia, y es un destacamento aparte el que ocupa las alturas.|Polybius points out Zeno’s contradiction: the cataphracts stand on the plain and yet charge from the hills. In the scenario they form up on the plain, facing the Aetolian cavalry, and a separate detachment holds the heights.'},
  liv3618:{ref:'Livio 36.18.2–4|Livy 36.18.2–4',work:'Ab urbe condita',lang:'la',url:PER('urn:cts:latinLit:phi0914.phi001.perseus-lat2:36.18'),
    o:'levis armaturae partem ante vallum in primo locavit, tum Macedonum robur, quos sarisophorus appellabant, velut firmamentum circa ipsas munitiones constituit. his ab sinistro cornu iaculatorum sagittariorumque et funditorum manum sub ipsis radicibus montis posuit, ut ex altiore loco nuda latera hostium incesserent. ab dextro Macedonibus ad ipsum munimentorum finem, qua loca usque ad mare invia palustri limo et voraginibus claudunt, elephantos cum adsueto praesidio posuit, post eos equites.',
    tr:'Colocó en primera línea, delante de la empalizada, una parte de la infantería ligera; después dispuso, como un baluarte en torno a las propias fortificaciones, la flor de los macedonios, a los que llamaban sarisóforos. A la izquierda de estos, al pie mismo del monte, puso un cuerpo de lanzadores de jabalina, arqueros y honderos, para que desde un lugar más alto hostigaran el flanco descubierto del enemigo. A la derecha de los macedonios, en el extremo mismo de las defensas, donde un terreno intransitable de lodo pantanoso y simas cierra el paso hasta el mar, puso los elefantes con su guardia habitual y, detrás de ellos, la caballería.|He stationed part of the light-armed troops in front, before the rampart; then he set the flower of the Macedonians, whom they called sarissophori, like a bulwark around the fortifications themselves. On their left wing, at the very foot of the mountain, he placed a body of javelin-men, archers and slingers, so that from higher ground they might assail the enemy’s exposed flank. On the right of the Macedonians, at the very end of the defences, where ground made impassable by marshy mud and quagmires closes the way as far as the sea, he placed the elephants with their usual guard and, behind them, the cavalry.',
    g:'El muro da +2 DEF a quien lo ocupa, y ni la caballería ni los elefantes pueden entrar en él. Los tiradores están en la ladera y los elefantes junto al pantano de la orilla, como en Livio.|The rampart gives +2 DEF to whoever holds it, and neither cavalry nor elephants can enter it. The skirmishers stand on the slope and the elephants by the marsh on the shore, as in Livy.'},
  liv3618b:{ref:'Livio 36.18.8|Livy 36.18.8',work:'Ab urbe condita',lang:'la',url:PER('urn:cts:latinLit:phi0914.phi001.perseus-lat2:36.18'),
    o:'multi temere subeuntes vallum transfixi sunt; et aut incepto irrito recessissent aut plures cecidissent, ni M. Porcius ab iugo Callidromi deiectis inde Aetolis et magna ex parte caesis — incautos enim et plerosque sopitos oppresserat — super imminentem castris collem apparuisset.',
    tr:'Muchos que se acercaban temerariamente a la empalizada fueron atravesados; y, o se habrían retirado sin lograr su propósito, o habrían caído más, si Marco Porcio, tras desalojar de la cresta del Calídromo a los etolios y matar a gran parte de ellos —pues los había sorprendido desprevenidos y, en su mayoría, dormidos—, no hubiera aparecido sobre la colina que dominaba el campamento.|Many who rashly came up under the rampart were run through; and they would either have withdrawn with their attempt frustrated or more would have fallen, had not Marcus Porcius, after dislodging the Aetolians from the ridge of Callidromon and killing a great part of them — for he had caught them off their guard and mostly asleep — appeared on the hill overlooking the camp.',
    g:'Catón empieza ya en las alturas del Calídromo. Si desaloja a los etolios, puede bajar por detrás del muro.|Cato begins already on the heights of Callidromon. If he dislodges the Aetolians, he can come down behind the rampart.'},
  mac117:{ref:'1 Macabeos 1.17–18|1 Maccabees 1.17–18',work:'Septuaginta|Septuagint',lang:'grc',url:PER('urn:cts:greekLit:tlg0527.tlg023.1st1K-grc1:1.17-1.19'),
    o:'καὶ εἰσῆλθεν εἰς Αἴγυπτον ὄχλῳ βαρεῖ, ἐν ἅρμασιν καὶ ἐλέφανσιν καὶ ἐν ἱππεῦσιν καὶ ἐν στόλῳ μεγάλῳ. καὶ συνεστήσατο πόλεμον πρὸς Πτολεμαῖον τὸν βασιλέα Αἰγύπτου· καὶ ἐνετράπη Πτολεμαῖος ἀπὸ προσώπου αὐτοῦ καὶ ἔφυγεν, καὶ ἔπεσαν τραυματίαι πολλοί.',
    tr:'Y entró en Egipto con una muchedumbre imponente, con carros y elefantes, con jinetes y con una gran flota. Y trabó combate con Ptolomeo, rey de Egipto; y Ptolomeo se volvió ante él y huyó, y cayeron muchos heridos.|And he entered Egypt with a heavy host, with chariots and elephants, with horsemen and with a great fleet. And he joined battle with Ptolemy, king of Egypt; and Ptolemy turned back before him and fled, and many fell wounded.',
    g:'El ejército de Antíoco IV incluye carros, elefantes y caballería, como dice el texto.|Antiochus IV’s army includes chariots, elephants and cavalry, as the text says.'},
  diod3014:{ref:'Diodoro 30.14|Diodorus 30.14',work:'Biblioteca histórica (fragmentos)|Library of History (fragments)',lang:'grc',url:null,
    sum:'Antíoco, que podía haber dado muerte a los egipcios vencidos, recorrió el campo a caballo gritando a los suyos que no los mataran y los cogieran vivos. Pronto recogió el fruto de esa habilidad, que contribuyó mucho a la toma de Pelusio y, después, a la conquista de Egipto.|Antiochus, who could have put the beaten Egyptians to death, rode about the field calling to his men not to kill them but to take them alive. He soon reaped the fruit of this shrewdness, which contributed greatly to the capture of Pelusium and, afterwards, to the conquest of Egypt.',
    g:'Un ejército que pierde el 60 % de su fuerza se desbanda: no hace falta aniquilarlo.|An army that loses 60% of its strength breaks: there is no need to annihilate it.'},
  mac639:{ref:'1 Macabeos 6.35 y 39|1 Maccabees 6.35, 39',work:'Septuaginta|Septuagint',lang:'grc',url:PER('urn:cts:greekLit:tlg0527.tlg023.1st1K-grc1:6.35-6.39'),
    o:'καὶ παρέστησαν ἐφʼ ἑκάστῳ ἐλέφαντι χιλίους ἄνδρας τεθωρακισμένους ἐν ἁλυσιδωτοῖς, καὶ περικεφαλαῖαι χαλκαῖ ἐπὶ τῶν κεφαλῶν αὐτῶν, καὶ πεντακοσία ἵππος διατεταγμένη ἑκάστῳ θηρίῳ ἐκλελεγμένη. […] ὡς δὲ ἔστιλβεν ὁ ἥλιος ἐπὶ τὰς χρυσᾶς ἀσπίδας, ἔστιλβεν τὰ ὄρη ἀπʼ αὐτῶν, καὶ κατηύγαζεν ὡς λαμπάδες πυρός.',
    tr:'Y pusieron junto a cada elefante mil hombres protegidos con cotas de malla, con cascos de bronce en la cabeza, y a cada fiera se le asignaron quinientos jinetes escogidos. […] Cuando el sol brilló sobre los escudos de oro, brillaron con ellos los montes y resplandecieron como antorchas de fuego.|And they stationed by each elephant a thousand men armoured in chain mail, with bronze helmets on their heads, and five hundred picked horsemen were assigned to each beast. […] When the sun shone on the golden shields, the mountains shone with them and blazed like torches of fire.',
    g:'Cada unidad de elefantes avanza con su falange «con cota de malla» detrás y jinetes escogidos al lado.|Each elephant unit advances with its phalanx “in chain mail” behind it and picked horsemen beside it.'},
  mac646:{ref:'1 Macabeos 6.43–44 y 46|1 Maccabees 6.43–44, 46',work:'Septuaginta|Septuagint',lang:'grc',url:PER('urn:cts:greekLit:tlg0527.tlg023.1st1K-grc1:6.43-6.46'),
    o:'καὶ εἶδεν Ἐλεαζὰρ ὁ Σαυαρὰν ἓν τῶν θηρίων τεθωρακισμένον θώραξιν βασιλικοῖς, καὶ ἦν ὑπεράγον πάντα τὰ θηρία, καὶ ὤφθη ὅτι ἐν αὐτῷ ἐστιν ὁ βασιλεύς. καὶ ἔδωκεν ἑαυτὸν τοῦ σῶσαι τὸν λαὸν αὐτοῦ, καὶ περιποιῆσαι αὐτῷ ὄνομα αἰώνιον. […] καὶ εἰσέδυ ὑπὸ τὸν ἐλέφαντα, καὶ ὑπέθηκεν αὐτῷ καὶ ἀνεῖλεν αὐτόν· καὶ ἔπεσεν ἐπὶ τὴν γῆν ἐπάνω αὐτοῦ, καὶ ἀπέθανεν ἐκεῖ.',
    tr:'Y Eleazar, el Savarán [el Avarán de otros manuscritos], vio una de las fieras acorazada con corazas reales, que sobresalía entre todas las fieras, y pareció que en ella estaba el rey. Y se entregó para salvar a su pueblo y ganarse un nombre eterno. […] Y se metió debajo del elefante, lo hirió desde abajo y lo mató; y el elefante cayó a tierra encima de él, y allí murió.|And Eleazar, the Sauaran [the Avaran of other manuscripts], saw one of the beasts armoured with royal armour, and it stood out above all the beasts, and it seemed that the king was on it. And he gave himself to save his people and to win for himself an everlasting name. […] And he crept under the elephant, struck it from beneath and killed it; and it fell to the ground on top of him, and he died there.',
    g:'La unidad de Eleazar suma +2 ATQ contra elefantes a los +2 que ya tiene la infantería ligera contra las bestias.|Eleazar’s unit adds +2 ATK against elephants to the +2 that light infantry already has against beasts.'},
  mac910:{ref:'1 Macabeos 9.10|1 Maccabees 9.10',work:'Septuaginta|Septuagint',lang:'grc',url:PER('urn:cts:greekLit:tlg0527.tlg023.1st1K-grc1:9.10'),
    o:'καὶ εἶπεν Ἰούδας Μή μοι γένοιτο ποιῆσαι τὸ πρᾶγμα τοῦτο, φυγεῖν ἀπʼ αὐτῶν· καὶ ἤγγικεν ὁ καιρὸς ἡμῶν, καὶ ἀποθάνωμεν ἀνδρίᾳ χάριν τῶν ἀδελφῶν ἡμῶν, καὶ μὴ καταλείπωμεν αἰτίαν τῇ δόξῃ ἡμῶν.',
    tr:'Y dijo Judas: «¡Lejos de mí hacer tal cosa, huir de ellos! Ha llegado nuestra hora: muramos con valor por nuestros hermanos y no dejemos mancha en nuestra gloria».|And Judas said: “Far be it from me to do such a thing, to flee from them! Our time has come: let us die bravely for our brothers and leave no reproach upon our glory.”',
    g:'Las tropas de Judas tienen «celo»: +1 ATQ en el cuerpo a cuerpo, también cuando responden a un ataque.|Judas’ troops have “zeal”: +1 ATK in melee, also when they counter an attack.'},
  mac915:{ref:'1 Macabeos 9.12 y 15–16|1 Maccabees 9.12, 15–16',work:'Septuaginta|Septuagint',lang:'grc',url:PER('urn:cts:greekLit:tlg0527.tlg023.1st1K-grc1:9.12-9.16'),
    o:'Βακχίδης δὲ ἦν ἐν τῷ δεξιῷ κέρατι, καὶ ἤγγισεν ἡ φάλαγξ ἐκ τῶν δύο μερῶν, καὶ ἐφώνουν ταῖς σάλπιγξιν […] καὶ συνετρίβη τὸ δεξιὸν κέρας ἀπʼ αὐτῶν, καὶ ἐδίωκεν ὀπίσω αὐτῶν ἕως Ἀζώτου ὄρους. καὶ οἱ εἰς τὸ ἀριστερὸν κέρας ἴδον ὅτι συνετρίβη τὸ δεξιὸν κέρας, καὶ ἐπέστρεψαν κατὰ πόδας Ἰούδα καὶ τῶν μετʼ αὐτοῦ ἐκ τῶν ὄπισθεν.',
    tr:'Báquides estaba en el ala derecha, y la falange se acercó por ambos lados, y tocaban las trompetas. […] Y el ala derecha fue deshecha por ellos, y la persiguió hasta el monte Azoto. Y los del ala izquierda vieron que el ala derecha había sido deshecha, y se volvieron tras los pasos de Judas y de los suyos, por la espalda.|Bacchides was on the right wing, and the phalanx drew near on both sides, and they sounded the trumpets. […] And the right wing was crushed by them, and he pursued them as far as Mount Azotus. And those on the left wing saw that the right wing had been crushed, and they turned and followed on the heels of Judas and his men from behind.',
    g:'Báquides está en el ala derecha, como en el texto. Si su ficha cae, el ejército seléucida se rinde.|Bacchides is on the right wing, as in the text. If his counter falls, the Seleucid army surrenders.'},
  mac1115:{ref:'1 Macabeos 11.15–17|1 Maccabees 11.15–17',work:'Septuaginta|Septuagint',lang:'grc',url:PER('urn:cts:greekLit:tlg0527.tlg023.1st1K-grc1:11.15-11.18'),
    o:'καὶ ἤκουσεν Ἀλέξανδρος, καὶ ἦλθεν ἐπʼ αὐτὸν ἐν πολέμῳ· καὶ ἐξήγαγεν Πτολεμαῖος καὶ ἀπήντησεν αὐτῷ ἐν χειρὶ ἰσχυρᾷ, καὶ ἐτροπώσατο αὐτόν. καὶ ἔφυγεν Ἀλέξανδρος εἰς τὴν Ἀραβίαν, τοῦ σκεπασθῆναι αὐτὸν ἐκεῖ· ὁ δὲ βασιλεὺς Πτολεμαῖος ὑψώθη. καὶ ἀφεῖλεν Ζαβδιὴλ ὁ Ἄραψ τὴν κεφαλὴν Ἀλεξάνδρου, καὶ ἀπέστειλεν τῷ Πτολεμαίῳ.',
    tr:'Alejandro lo supo y marchó contra él en son de guerra; y Ptolomeo sacó sus tropas, le salió al encuentro con mano fuerte y lo puso en fuga. Y Alejandro huyó a Arabia para ponerse allí a cubierto; y el rey Ptolomeo fue ensalzado. Y Zabdiel el árabe le cortó la cabeza a Alejandro y se la envió a Ptolomeo.|Alexander heard of it and came against him in war; and Ptolemy led out his forces, met him with a strong hand and routed him. And Alexander fled to Arabia to find shelter there; and King Ptolemy was exalted. And Zabdiel the Arab cut off Alexander’s head and sent it to Ptolemy.',
    g:'La batalla se decide cuando cae un general: aquí los dos reyes combaten con su caballería.|The battle is decided when a general falls: here both kings fight with their cavalry.'},
  jos13117:{ref:'Flavio Josefo, Antigüedades judías 13.117|Flavius Josephus, Jewish Antiquities 13.117',work:'Antigüedades judías|Jewish Antiquities',lang:'grc',url:PER('urn:cts:greekLit:tlg0526.tlg001.perseus-grc2:13.117'),
    o:'συνέβη δὲ ἐν τῇ μάχῃ τὸν ἵππον τὸν Πτολεμαίου φωνῆς ἀκούσαντα ἐλέφαντος ταραχθῆναι καὶ τὸν Πτολεμαῖον ἀποσεισάμενον καταβαλεῖν, τοὺς δὲ πολεμίους ἰδόντας ἐπʼ αὐτὸν ὁρμῆσαι καὶ τραύματα πολλὰ δόντας αὐτῷ κατὰ τῆς κεφαλῆς εἰς κίνδυνον τὸν περὶ θανάτου καταστῆσαι.',
    tr:'Ocurrió en la batalla que el caballo de Ptolomeo, al oír el bramido de un elefante, se espantó y, sacudiéndose a Ptolomeo de encima, lo derribó; y que los enemigos, al verlo, se lanzaron sobre él y, causándole muchas heridas en la cabeza, lo pusieron en peligro de muerte.|It happened in the battle that Ptolemy’s horse, on hearing the cry of an elephant, took fright and, shaking Ptolemy off, threw him; and that the enemy, seeing this, rushed at him and, dealing him many wounds on the head, brought him into danger of death.',
    g:'Los elefantes espantan a los caballos: la caballería que ataca a un elefante, o junto a uno enemigo, sufre −2 ATQ.|Elephants frighten horses: cavalry attacking an elephant, or next to an enemy one, suffers −2 ATK.'},
  just3810:{ref:'Justino 38.10.9–10|Justin 38.10.9–10',work:'Epítome de las Historias filípicas de Pompeyo Trogo|Epitome of the Philippic Histories of Pompeius Trogus',lang:'la',url:'https://www.thelatinlibrary.com/justin/38.html',
    o:'Quae cum nuntiata Antiocho essent, auxilium proximis laturus cum ea manu, quae secum hiemabat, progreditur. In itinere obvium regem Parthorum habuit, adversus quem fortius quam exercitus eius dimicavit. Ad postremum tamen, cum virtute hostes vincerent, metu suorum desertus occiditur.',
    tr:'Cuando se lo anunciaron a Antíoco, se puso en marcha para socorrer a los más próximos con la tropa que invernaba con él. En el camino se encontró con el rey de los partos, contra el que combatió con más valor que su ejército. Al final, sin embargo, como los enemigos vencían por su valor, abandonado por el miedo de los suyos, fue muerto.|When this was reported to Antiochus, he set out to bring help to those nearest with the force that was wintering with him. On the way he met the king of the Parthians, against whom he fought more bravely than his army. In the end, however, as the enemy were prevailing by their valour, he was deserted through the fear of his own men and killed.',
    g:'Antíoco es tropa escogida y combate con su guardia; su ejército es pequeño y está rodeado de arqueros a caballo.|Antiochus counts as picked troops and fights with his guard; his army is small and ringed by horse archers.'},
  diod3416:{ref:'Diodoro 34/35.16–17|Diodorus 34/35.16–17',work:'Biblioteca histórica (fragmentos)|Library of History (fragments)',lang:'grc',url:null,
    sum:'Los amigos de Antíoco le pedían que no trabara combate con los partos, muy superiores en número; él no les hizo caso y recibió con valor la acometida de los bárbaros. Ateneo, su general, que había cometido muchos abusos al alojar a las tropas, fue el primero en huir y abandonó a Antíoco, pero tuvo el final que merecía: en las aldeas a las que había maltratado nadie quiso recibirlo ni darle de comer, y murió de hambre vagando por el campo.|Antiochus’ friends begged him not to join battle with the Parthians, who were far superior in numbers; he paid them no heed and bravely met the onset of the barbarians. Athenaeus, his general, who had committed many abuses in billeting the troops, was the first to flee and abandoned Antiochus, but met the end he deserved: in the villages he had mistreated no one would take him in or feed him, and he died of hunger wandering the countryside.',
    g:'Las unidades de Ateneo son «vacilantes»: −2 ATQ y −2 DEF cuando el general enemigo está a 2 casillas o menos.|Athenaeus’ units are “wavering”: −2 ATK and −2 DEF when the enemy general is within 2 squares.'},
  jos13391:{ref:'Flavio Josefo, Antigüedades judías 13.391|Flavius Josephus, Jewish Antiquities 13.391',work:'Antigüedades judías|Jewish Antiquities',lang:'grc',url:PER('urn:cts:greekLit:tlg0526.tlg001.perseus-grc2:13.391'),
    o:'ἀναχωροῦντος δὲ τοῦ Ἄραβος τὰ πρῶτα, ἔπειτα μετὰ μυρίων ἱππέων ἐξαίφνης ἐπιφανέντος ὑπαντήσας τούτοις Ἀντίοχος καρτερῶς ἐμάχετο, καὶ δὴ νικῶν ἀπέθανεν παραβοηθῶν τῷ πονοῦντι μέρει. πεσόντος δʼ Ἀντιόχου καὶ τὸ στράτευμα φεύγει εἰς Κανὰ κώμην, ἔνθα τὸ πλεῖον αὐτῶν λιμῷ φθείρεται.',
    tr:'El árabe se retiró al principio y después apareció de repente con diez mil jinetes; Antíoco les salió al encuentro y combatió con firmeza, y, cuando ya vencía, murió al acudir en ayuda de la parte que flaqueaba. Caído Antíoco, también el ejército huye a la aldea de Caná, donde la mayor parte perece de hambre.|The Arab withdrew at first and then suddenly appeared with ten thousand horsemen; Antiochus went to meet them and fought stoutly, and, when he was already winning, died as he went to the help of the part that was in trouble. When Antiochus had fallen, the army too flees to the village of Cana, where most of them perish of hunger.',
    g:'Aretas alinea sobre todo caballería ligera y arqueros a caballo: rápidos, pero débiles en el choque. Antíoco es tropa escogida, pero si su ficha cae se pierde la batalla.|Aretas fields mostly light cavalry and horse archers: fast, but weak in the clash. Antiochus counts as picked troops, but if his counter falls the battle is lost.'}
};
const GLOSS={
  sarisa:{t:'Sarisa|Sarissa',o:'σάρισα',d:'Pica de unos 5 a 7 m que los falangitas manejaban con ambas manos. Las primeras filas presentaban un muro de puntas; las de atrás, con las picas inclinadas, frenaban los proyectiles.|A pike of some 5 to 7 m wielded with both hands by phalangites. The front ranks presented a wall of points; the rear ranks, with pikes raised at an angle, helped to stop missiles.'},
  falange:{t:'Falange|Phalanx',o:'φάλαγξ',d:'Formación cerrada y profunda de infantería pesada armada con sarisa. Casi imbatible de frente en terreno llano, pero vulnerable por los flancos y en terreno quebrado.|A close, deep formation of heavy infantry armed with the sarissa. Almost unbeatable from the front on level ground, but vulnerable on the flanks and on broken ground.'},
  argiraspides:{t:'Argiráspides|Argyraspides',o:'ἀργυράσπιδες',d:'«Escudos de plata». El nombre lo llevaron los veteranos de Alejandro y, más tarde, la guardia de infantería de los reyes seléucidas.|“Silver Shields”. The name was borne by Alexander’s veterans and, later, by the infantry guard of the Seleucid kings.'},
  agema:{t:'Agema|Agema',o:'ἄγημα',d:'Unidad de guardia, de infantería o de caballería, que combatía junto al rey. En Magnesia, según Livio, la formaban jinetes medos escogidos.|A guard unit, of infantry or cavalry, that fought beside the king. At Magnesia, according to Livy, it was made up of picked Median horsemen.'},
  hetairoi:{t:'Hetairoi|Hetairoi',o:'ἑταῖροι',d:'«Compañeros». Caballería pesada aristocrática de tradición macedonia, armada con la lanza (ξυστόν). Diodoro cuenta que en Gaza combatieron primero con las lanzas y luego con la espada.|“Companions”. Aristocratic heavy cavalry in the Macedonian tradition, armed with the lance (ξυστόν). Diodorus says that at Gaza they fought first with lances and then with swords.'},
  catafractos:{t:'Catafractos|Cataphracts',o:'κατάφρακτοι',d:'Jinetes cubiertos de armadura, a menudo también sus caballos. Aparecen en el ejército seléucida a fines del siglo III a. C.; Polibio los menciona en Panio (200).|Horsemen covered in armour, often with armoured horses too. They appear in the Seleucid army at the end of the 3rd century BC; Polybius mentions them at Panium (200).'},
  elefantes:{t:'Elefantes de guerra|War elephants',o:'θηρία',d:'Los seléucidas usaban elefantes indios; los ptolomeos, elefantes africanos capturados en la costa del mar Rojo, más pequeños. Llevaban torres con guerreros y un conductor al que las fuentes llaman simplemente «el indio» (Ἰνδός).|The Seleucids used Indian elephants; the Ptolemies used smaller African elephants captured on the Red Sea coast. They carried towers with fighters and a driver whom the sources simply call “the Indian” (Ἰνδός).'},
  carros:{t:'Carros falcados|Scythed chariots',o:'ἅρματα δρεπανηφόρα · quadrigae falcatae',d:'Carros de cuatro caballos con cuchillas en el yugo y en los ejes, herencia del ejército aqueménida. Livio describe su armamento en detalle (37.41.6–7).|Four-horse chariots with blades on the yoke and axles, inherited from the Achaemenid army. Livy describes their equipment in detail (37.41.6–7).'},
  peltastas:{t:'Peltastas|Peltasts',o:'πελτασταί',d:'En origen, infantería con escudo ligero (πέλτη). En época helenística el término designa tropas de armamento intermedio, a veces de élite.|Originally infantry with a light shield (πέλτη). In the Hellenistic period the term covers troops of intermediate equipment, sometimes elite.'},
  tarentinos:{t:'Tarentinos|Tarentines',o:'Ταραντῖνοι',d:'Jinetes ligeros con jabalinas. El nombre, tomado de Tarento, pasó a designar ese estilo de combate más que un origen.|Light horsemen with javelins. The name, taken from Tarentum, came to denote that style of fighting rather than an origin.'},
  dahas:{t:'Dahas|Dahae',o:'Δάαι · Dahae',d:'Pueblo nómada del norte de Irán, al este del Caspio. En los ejércitos seléucidas servían como arqueros a caballo.|A nomadic people of northern Iran, east of the Caspian. In Seleucid armies they served as horse archers.'},
  cretenses:{t:'Arqueros cretenses|Cretan archers',o:'Κρῆτες',d:'Arqueros mercenarios famosos en todo el Mediterráneo; los emplearon todos los reinos helenísticos y también Roma.|Mercenary archers famous throughout the Mediterranean; every Hellenistic kingdom employed them, and so did Rome.'},
  machimoi:{t:'Egipcios en la falange|Egyptians in the phalanx',o:'μάχιμοι',d:'Los máchimoi eran la clase guerrera egipcia. Para Rafia, Ptolomeo IV armó y entrenó a la macedonia a unos 20.000 egipcios, que combatieron en la falange.|The machimoi were the Egyptian warrior class. For Raphia, Ptolemy IV armed and trained some 20,000 Egyptians in the Macedonian manner, and they fought in the phalanx.'},
  galatas:{t:'Gálatas|Galatians',o:'Γαλάται',d:'Celtas que pasaron a Asia Menor en 278/277 y se asentaron en el centro de Anatolia. Fueron mercenarios muy buscados.|Celts who crossed into Asia Minor in 278/277 and settled in central Anatolia. They were much sought-after mercenaries.'},
  legion:{t:'Legión manipular|Manipular legion',o:'legio',d:'Infantería romana articulada en manípulos, con pilum y gladius. Más flexible que la falange en terreno irregular.|Roman infantry organised in maniples, with pilum and gladius. More flexible than the phalanx on uneven ground.'},
  empalizada:{t:'Empalizada de hierro|Iron palisade',o:'χάραξ σεσιδηρωμένος',d:'Diodoro describe en Gaza una empalizada o barrera guarnecida de hierro y unida con cadenas, que la infantería ligera tendía delante de los elefantes.|At Gaza, Diodorus describes a palisade or barrier fitted with iron and bound with chains, which the light infantry stretched out in front of the elephants.'},
  satrapa:{t:'Sátrapa|Satrap',o:'σατράπης',d:'Gobernador de una provincia en el Imperio aqueménida; Alejandro y sus sucesores conservaron el cargo. Seleuco fue sátrapa de Babilonia antes de ser rey.|Governor of a province in the Achaemenid Empire; Alexander and his successors kept the office. Seleucus was satrap of Babylon before he was king.'},
  diadocos:{t:'Diádocos|Diadochi',o:'διάδοχοι',d:'«Sucesores»: los generales de Alejandro que se repartieron y disputaron su imperio entre 323 y 281 a. C. Corupedio fue la última de sus batallas.|“Successors”: the generals of Alexander who divided and fought over his empire between 323 and 281 BC. Corupedium was the last of their battles.'},
  tracios:{t:'Tracios|Thracians',o:'Θρᾷκες',d:'Pueblos del norte del Egeo, núcleo del reino de Lisímaco. Servían como infantería ligera y como caballería en todos los ejércitos helenísticos.|Peoples of the northern Aegean, the core of Lysimachus’ kingdom. They served as light infantry and as cavalry in every Hellenistic army.'},
  xistoforos:{t:'Xistóforos|Xystophoroi',o:'ξυστοφόροι',d:'Jinetes armados con el ξυστόν, la lanza de la caballería macedonia. Polibio los coloca en el extremo derecho de la línea de Antíoco III en Apolonia, al mando de Ardis.|Horsemen armed with the ξυστόν, the lance of the Macedonian cavalry. Polybius places them on the far right of Antiochus III’s line at Apollonia, under Ardys.'},
  tureoforos:{t:'Tureóforos|Thureophoroi',o:'θυρεοφόροι · θυρεαφόροι',d:'Infantería armada con el θυρεός, un escudo ovalado de origen celta; más ligera que la falange y más sólida que los peltastas. Se generalizó en el siglo III a. C.|Infantry armed with the θυρεός, an oval shield of Celtic origin; lighter than the phalanx and steadier than peltasts. It became widespread in the 3rd century BC.'},
  hiparquia:{t:'Hiparquía|Hipparchy',o:'ἱππαρχία',d:'Regimiento de caballería. En el Ario, según Polibio, los bactrianos cargaron por hiparquías sucesivas: Antíoco rechazó la primera, pero la segunda y la tercera pusieron en apuros a sus hombres.|A cavalry regiment. At the Arius, according to Polybius, the Bactrians charged by successive hipparchies: Antiochus drove back the first, but the second and third put his men in difficulties.'},
  anabasis:{t:'Anábasis|Anabasis',o:'ἀνάβασις',d:'«Marcha tierra adentro». Se llama así a la expedición de Antíoco III a las satrapías orientales (212–205 a. C.), que lo llevó a Armenia, Partia, Bactria y la India y le valió el título de «Grande».|“March up-country”. The name is given to Antiochus III’s expedition to the eastern satrapies (212–205 BC), which took him to Armenia, Parthia, Bactria and India and earned him the title “the Great”.'},
  hipaspistas:{t:'Hipaspistas|Hypaspists',o:'ὑπασπισταί',d:'«Portadores de escudo». Infantería de guardia de los reyes macedonios desde Filipo II; en Panio, según el relato que recoge Polibio, formaban con el rey detrás de los elefantes.|“Shield-bearers”. Guard infantry of the Macedonian kings since Philip II; at Panium, according to the account Polybius reports, they stood with the king behind the elephants.'},
  etolios:{t:'Etolios|Aetolians',o:'Αἰτωλοί',d:'Pueblo de Grecia central organizado en una liga federal. Dieron mercenarios a todos los reinos: Escopas mandaba a los de Ptolomeo V en Panio, y en 191 fueron los aliados de Antíoco III en Grecia.|A people of central Greece organised in a federal league. They supplied mercenaries to every kingdom: Scopas commanded those of Ptolemy V at Panium, and in 191 they were Antiochus III’s allies in Greece.'},
  calidromo:{t:'Calídromo|Callidromon',o:'Καλλίδρομον',d:'Monte que cierra por el sur el paso de las Termópilas. Por sus senderos rodearon los persas a Leónidas en 480 a. C. y Catón a Antíoco III en 191.|The mountain that closes the pass of Thermopylae on the south. By its paths the Persians outflanked Leonidas in 480 BC and Cato outflanked Antiochus III in 191.'},
  velites:{t:'Vélites|Velites',o:'velites',d:'Infantería ligera de la legión manipular, armada con jabalinas, espada y un escudo pequeño; abría el combate delante de la línea.|Light infantry of the manipular legion, armed with javelins, a sword and a small shield; they opened the fighting in front of the line.'},
  clerucos:{t:'Clerucos|Cleruchs',o:'κληροῦχοι',d:'Soldados a los que los Ptolomeos entregaban un lote de tierra (κλῆρος) en Egipto a cambio de servir en el ejército cuando se les llamaba.|Soldiers to whom the Ptolemies granted a plot of land (κλῆρος) in Egypt in return for serving in the army when called up.'},
  cotas:{t:'Cotas de malla|Chain mail',o:'ἁλυσιδωτοὶ θώρακες',d:'El Primer libro de los Macabeos (6.35) dice que los infantes que escoltaban a los elefantes en Bet Zacarías iban protegidos con cota de malla y casco de bronce. La malla, de origen celta, se difundió por el Mediterráneo en el siglo II a. C.|The First Book of Maccabees (6.35) says that the foot soldiers escorting the elephants at Beth Zechariah were protected by chain mail and bronze helmets. Mail, of Celtic origin, spread around the Mediterranean in the 2nd century BC.'},
  hasmoneos:{t:'Macabeos y asmoneos|Maccabees and Hasmonaeans',o:'Μακκαβαῖος · Ἀσαμωναῖοι',d:'«Macabeo» es el sobrenombre de Judas; se suele explicar como «martillo». Sus hermanos y descendientes, los asmoneos, gobernaron Judea como sumos sacerdotes y luego como reyes hasta 37 a. C.|“Maccabeus” is Judas’ byname; it is usually explained as “hammer”. His brothers and descendants, the Hasmonaeans, ruled Judaea as high priests and then as kings until 37 BC.'},
  acra:{t:'Acra|Akra',o:'ἄκρα',d:'Ciudadela que Antíoco IV levantó en Jerusalén y guarneció con tropas. Resistió a los Macabeos hasta 141 a. C.; el asedio de Judas en 162 provocó la campaña de Lisias.|The citadel that Antiochus IV built in Jerusalem and garrisoned. It held out against the Maccabees until 141 BC; Judas’ siege in 162 brought on Lysias’ campaign.'},
  diadema:{t:'Diadema|Diadem',o:'διάδημα',d:'Cinta ceñida a la cabeza, símbolo de la realeza helenística desde Alejandro. Según el Primer libro de los Macabeos y Josefo, Ptolomeo VI llegó a ceñirse en Antioquía dos diademas: la de Egipto y la de Asia.|A band tied round the head, the symbol of Hellenistic kingship since Alexander. According to the First Book of Maccabees and Josephus, Ptolemy VI came to wear two diadems at Antioch: that of Egypt and that of Asia.'},
  partos:{t:'Partos|Parthians',o:'Πάρθοι',d:'Pueblo iranio que, con la dinastía arsácida, arrebató a los seléucidas Irán y Mesopotamia a lo largo de los siglos III y II a. C. Su ejército combinaba arqueros a caballo, que disparaban sin dejarse alcanzar, y catafractos.|An Iranian people who, under the Arsacid dynasty, took Iran and Mesopotamia from the Seleucids in the course of the 3rd and 2nd centuries BC. Their army combined horse archers, who shot without letting themselves be caught, and cataphracts.'},
  nabateos:{t:'Nabateos|Nabataeans',o:'Ναβαταῖοι',d:'Pueblo árabe con capital en Petra, enriquecido por las caravanas del incienso. Ya en 312 a. C. resistieron las expediciones de Antígono y Demetrio; con Aretas III llegaron a dominar Damasco.|An Arab people with their capital at Petra, enriched by the incense caravans. As early as 312 BC they withstood the expeditions of Antigonus and Demetrius; under Aretas III they came to control Damascus.'}
};
